<?php
declare(strict_types=1);require_once __DIR__.'/../config/koneksi.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();if(($_SESSION['user_role']??'')!=='student'){header('Location: /auth/student_login.php');exit;}$uid=(int)$_SESSION['user_id'];$q=db()->prepare("SELECT m.*,c.name classroom_name,c.code FROM classroom_members m JOIN classrooms c ON c.id=m.classroom_id WHERE m.user_id=? AND m.membership_status='active' ORDER BY m.id DESC");$q->execute([$uid]);$rows=$q->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Account · EnglAI</title><link rel="stylesheet" href="/assets/css/mvp.css"></head><body><div class="stars"></div><header class="nav"><a class="brand" href="/">EnglAI</a><a class="button secondary" href="/auth/logout.php">Logout</a></header><main class="shell"><section class="card dashboard-hero"><span class="eyebrow">Permanent Student Account</span><h1><?=htmlspecialchars((string)$_SESSION['user_name'])?></h1><p class="muted">Progress dapat dilanjutkan pada perangkat lain setelah login.</p></section><section class="card"><h2>My Classrooms</h2><?php if(!$rows):?><div class="empty">Join Classroom dari Public Page setelah login.</div><?php endif;?><?php foreach($rows as $r):?><article class="row"><div><b><?=htmlspecialchars($r['classroom_name'])?></b><br><span class="code"><?=htmlspecialchars($r['code'])?></span></div><a class="button primary" href="/student/resume.php?member_id=<?=(int)$r['id']?>">Open Classroom</a></article><?php endforeach;?></section></main></body></html>
